  signal game_q, basic_u3_q, basic_u2_q : std_logic_vector(7 downto 0) := (others => '1');
  attribute rom_style : string;
  attribute rom_style of game_u4, basic_u3, basic_u2 : constant is "block";
begin
  process(clk)
    variable index : natural range 0 to 8191;
  begin
    if rising_edge(clk) then
      index := to_integer(unsigned(address(12 downto 0)));
      -- Testbenches can shorten the original welcome delay without changing hardware ROM bytes.
      if SIM_FAST_BOOT and (index = 16#13F3# or index = 16#1969#) then
        game_q <= x"01";
      elsif SIM_FAST_BOOT and (index = 16#13F4# or index = 16#196A#) then
        game_q <= x"00";
      else
        game_q <= game_u4(index);
      end if;
      basic_u3_q <= basic_u3(index);
      basic_u2_q <= basic_u2(index);
    end if;
  end process;
  data <= basic_u3_q when address(15 downto 13) = "000" and basic_bank = '1' else
          game_q     when address(15 downto 13) = "000" else
          basic_u2_q when address(15 downto 13) = "001" else
          x"FF";
end architecture;
